-- Retake Faronaar (36811): the bonus objective's bar had nothing to fill it but Imp Mother Fecunda. Faronaar has no
-- sniffed spawns, so its Legion force is hand-placed on the navmesh inside the quest's map area: the bar's own credit
-- entries (Burning Hellion, Mo'arg Crusher, Lord Perdition, Blerg) and the mobs whose KillCredit is Legion Skyterror or
-- Mo'arg Crusher, plus the Legion Portals and Libram of Fel Knowledge books it counts.
-- The templates whose faction is the placeholder 35 (friendly) take 1786, the faction of the sniffed Faronaar demons.
UPDATE `creature_template` SET `faction`=1786 WHERE `entry` IN (89731, 103180, 103231, 103363, 90663, 106629) AND `faction`=35;

-- portals and librams are used once per player, then hidden from that player until they respawn
UPDATE `gameobject_template` SET `Data5`=1 WHERE `entry` IN (239676, 240323);

DELETE FROM `creature` WHERE `guid` BETWEEN 12201200 AND 12201238;

DELETE FROM `gameobject` WHERE `guid` BETWEEN 12201200 AND 12201213;
